def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    difference = new - old
    return {
        "value": difference,
        "trace": {
            "old_net_outflows": old,
            "new_net_outflows": new,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
